    "typeLabel": "Para cuando duele",
    "emoji": "☁️",
    "body": "Mary, Mi Mai, niña de fuego y nube: aquí estoy.\n\nLa palabra “demasiado” la traduje a “verdadera”. Mai, si te estás peleando contigo, déjame entrar un segundo: no tienes que merecer consuelo. El consuelo ya es tuyo. Descansa de ser fuerte. Aquí nadie te va a calificar el llanto.\n\nJunio endulza el aire. Tú también. Puedes doblar esta carta y ponerla bajo la almohada. Está hecha para eso.\n\nCarta 259. Si estás cansada, no tienes que leerla toda. Quédate con una frase. Basta.\n\nMai, tu ausencia también enseña: enseña lo esencial que eres.",
