    "body": "Hoy elijo nombrarte con cariño y sin prisa.\n\nTu espontaneidad me visitó como un flash. Me gusta tu cara cuando no está posando. Me gusta tu voz cuando se vuelve chiquita. Me gusta esa forma tuya de ocupar el mundo como si todavía no creyeras que mereces tanto espacio… y aun así lo llenas de magia.\n\nSeptiembre te queda: es un mes con memoria y con comienzo. Te escribo como quien enciende una lamparita y se va, dejándote luz.\n\nVan 361 maneras distintas de decirte lo mismo esencial: importas.\n\nMai, no eres demasiado. El mundo a veces es demasiado chico para ti.",
