    "body": "Hoy quiero que leas esto como quien recibe un abrazo tardío.\n\nPensé en tus heridas con las manos ocupadas de respeto. Mai, si te estás peleando contigo, déjame entrar un segundo: no tienes que merecer consuelo. El consuelo ya es tuyo. Descansa de ser fuerte. Aquí nadie te va a calificar el llanto.\n\nLa palabra “demasiado” la traduje a “verdadera”. Puedes doblar esta carta y ponerla bajo la almohada. Está hecha para eso.\n\nCarta 364. Si estás cansada, no tienes que leerla toda. Quédate con una frase. Basta.\n\nHay amores que se dicen en voz baja. El mío también sabe gritar suave.",
